#!/usr/bin/env python3
# Бумажный бот «ордер перед стенкой» (спот Binance). Реальные деньги не используются.
# Использует движок исполнения из obbot.py (очередь, задержка, комиссии, журнал).
import asyncio, json, os, sqlite3, statistics, time, traceback
import aiohttp
from aiohttp import web
import obbot
from obbot import Engine, feed, SCHEMA, HTML

CFG = dict(obbot.CFG)
CFG.update(
    PAIRS=["SOLUSDT", "XRPUSDT", "NEARUSDT", "SANDUSDT", "DOGEUSDT", "ADAUSDT"],
    ORDER_TTL=1800.0,        # сколько живёт заявка перед стенкой, сек
    CANCEL_OBI=-2.0,         # отмена по дисбалансу отключена
    HOLD_SEC=1800.0,         # максимум в позиции, сек
    COOLDOWN=60.0,
    TP_BPS=80.0,             # тейк-профит от входа, б.п.
    STOP_FROM_ENTRY_BPS=80.0, # стоп от цены входа, б.п. (0 = стоп под стенкой)
    WALL_MULT=5.0,           # стенка = уровень крупнее МЕСТНОЙ медианы (10 соседей с каждой стороны) в N раз
    WALL_MIN_USDT=8000.0,    # и не меньше этой суммы
    MIN_DIST_BPS=8.0,        # стенка не ближе чем на столько от лучшей цены
    MAX_DIST_BPS=60.0,       # и не дальше
    WALL_AGE=10.0,           # стенка должна простоять столько сек (фильтр мигающих)
    STOP_BELOW_BPS=10.0,     # стоп ниже стенки на столько б.п.
    MAX_RISK_BPS=120.0,      # не входить, если до стопа дальше
    EXIT_ON_WALL_GONE=False, # выйти, если стенку сняли (данные показали, что вредно)
    POLL=5.0,                # период опроса глубины, сек (на все пары)
    SHADOW_SEC=1800.0,       # сколько писать путь цены после входа
    STUDY_SEC=1800.0,        # сколько следить за стенкой и контрольным уровнем
)
DB = os.environ.get("WALL_DB", "/opt/trading-bot/ob_wall3.db")
PORT = int(os.environ.get("WALL_PORT", "8091"))
SCHEMA2 = SCHEMA + """
CREATE TABLE IF NOT EXISTS paths(id INTEGER PRIMARY KEY, ts REAL, symbol TEXT, entry REAL,
 stop REAL, wall REAL, wall_usdt REAL, path TEXT);
CREATE TABLE IF NOT EXISTS levels(id INTEGER PRIMARY KEY, ts REAL, symbol TEXT, kind TEXT,
 price REAL, usdt REAL, tick REAL, dist REAL, path TEXT);
"""


class WallEngine(Engine):
    def __init__(self, cfg, db):
        super().__init__(cfg, db)
        self.shadow, self.study = [], []
        for s in self.s.values():
            s.update(wall=None, seen={}, snap={}, bids_snap=[], asks_snap=[], snap_t=0.0, tracked={})

    def _maybe_enter(self, s, now):      # входы только по снимкам глубины
        return

    def _queue(self, o, bids, asks):     # очередь, увиденная при выставлении
        return o.get("q0", 0.0)

    def on_book(self, sym, bids, asks, now):
        super().on_book(sym, bids, asks, now)
        keep = []
        for g in self.shadow:
            if g["sym"] == sym and bids:
                if now - g["last"] >= 10:
                    g["path"].append([int(now - g["t"]), bids[0][0]])
                    g["last"] = now
                if now - g["t"] >= self.c["SHADOW_SEC"]:
                    self.db.execute("INSERT INTO paths(ts,symbol,entry,stop,wall,wall_usdt,path) VALUES(?,?,?,?,?,?,?)",
                                    (g["t"], sym, g["entry"], g["stop"], g["wall"], g["usdt"], json.dumps(g["path"])))
                    self.db.commit()
                    continue
            keep.append(g)
        self.shadow = keep
        keep = []
        for g in self.study:
            if g["sym"] == sym and bids:
                if now - g["last"] >= 10:
                    g["path"].append([int(now - g["t"]), bids[0][0]])
                    g["last"] = now
                if now - g["t"] >= self.c["STUDY_SEC"]:
                    self.db.execute("INSERT INTO levels(ts,symbol,kind,price,usdt,tick,dist,path) VALUES(?,?,?,?,?,?,?,?)",
                                    (g["t"], sym, g["kind"], g["price"], g["usdt"], g["tick"], g["dist"],
                                     json.dumps(g["path"])))
                    self.db.commit()
                    continue
            keep.append(g)
        self.study = keep

    def _entered(self, s, o, now):
        super()._entered(s, o, now)
        s["pos"].update(stop=o["stop"], wall=o["wall"], usdt=o["wall_usdt"])
        self.shadow.append(dict(sym=s["name"], t=now, last=now, entry=o["price"], stop=o["stop"],
                                wall=o["wall"], usdt=o["wall_usdt"], path=[[0, o["price"]]]))

    def _manage(self, s, now):
        p = s["pos"]
        if s["mkt"] or "stop" not in p:
            return super()._manage(s, now)
        bid = s["bids"][0][0]
        why = "stop" if bid <= p["stop"] else ("timeout" if now - p["t"] >= self.c["HOLD_SEC"] else None)
        if why:
            s["order"] = None
            s["mkt"] = dict(t=now + self.c["LATENCY"], why=why)
            self.log(now, s["name"], why, bid, "")

    # ---------- снимок глубины (REST) ----------
    def on_snapshot(self, sym, bids, asks, now):
        if sym not in self.s or len(bids) < 5 or not asks:
            return
        c, s = self.c, self.s[sym]
        s["snap"] = {p: q for p, q in bids}
        s["bids_snap"], s["asks_snap"], s["snap_t"] = bids, asks, now
        bid0 = bids[0][0]
        notion = [p * q for p, q in bids]
        loc = self._local_med(notion)
        cands = {}
        for i, ((p, q), nv) in enumerate(zip(bids, notion)):
            dist = (bid0 - p) / bid0 * 1e4
            if c["MIN_DIST_BPS"] <= dist <= c["MAX_DIST_BPS"] and nv >= max(c["WALL_MIN_USDT"], c["WALL_MULT"] * loc[i]):
                cands[p] = (nv, dist)
        s["seen"] = {p: s["seen"].get(p, now) for p in cands}
        ripe = sorted((d, p, nv) for p, (nv, d) in cands.items() if now - s["seen"][p] >= c["WALL_AGE"])
        s["wall"] = dict(price=ripe[0][1], usdt=ripe[0][2], dist=ripe[0][0]) if ripe else None
        self._study_new(s, bids, notion, statistics.median(notion), cands, ripe, now)

        o, pos = s["order"], s["pos"]
        if pos and "wall" in pos and c["EXIT_ON_WALL_GONE"] and not s["mkt"]:
            if s["snap"].get(pos["wall"], 0.0) * pos["wall"] < 0.3 * pos["usdt"]:
                s["order"] = None
                s["mkt"] = dict(t=now + c["LATENCY"], why="wall_gone")
                self.log(now, sym, "wall_gone", pos["wall"], "")
            return
        if o and not pos and o["side"] == "buy" and "wall" in o:
            if s["snap"].get(o["wall"], 0.0) * o["wall"] < 0.5 * o["wall_usdt"]:
                s["order"] = None
                self.log(now, sym, "buy_cancel", o["price"], "стенку сняли")
            return
        if pos or o or s["mkt"] or now < s["cool"] or not s["wall"] or now - s["t_book"] > 2:
            return
        w = s["wall"]
        gaps = [round(bids[i][0] - bids[i + 1][0], 10) for i in range(len(bids) - 1)]
        tick = min(g for g in gaps if g > 0)
        price = round(w["price"] + tick, 10)
        if c["STOP_FROM_ENTRY_BPS"]:
            stop = price * (1 - c["STOP_FROM_ENTRY_BPS"] / 1e4)
        else:
            stop = w["price"] * (1 - c["STOP_BELOW_BPS"] / 1e4)
        risk = (price - stop) / price * 1e4
        if price >= bid0 or risk > c["MAX_RISK_BPS"]:
            return
        s["order"] = dict(side="buy", price=price, qty=c["NOTIONAL"] / price, t_place=now,
                          t_act=now + c["LATENCY"], queue=None, obi=w["dist"], spread=s["spread"],
                          wall=w["price"], wall_usdt=w["usdt"], stop=stop, q0=s["snap"].get(price, 0.0))
        self.log(now, sym, "buy_order", price, "стенка %.5g %.0f USDT, %.1f б.п. ниже, риск %.0f б.п." %
                 (w["price"], w["usdt"], w["dist"], risk))

    @staticmethod
    def _local_med(notion, k=10):
        out = []
        for i in range(len(notion)):
            w = notion[max(0, i - k):i] + notion[i + 1:i + 1 + k]
            out.append(statistics.median(w) if w else 0.0)
        return out

    def _study_new(self, s, bids, notion, med, cands, ripe, now):
        """Для каждой новой стенки заводим запись и контрольный уровень на том же расстоянии."""
        s["tracked"] = {p: t for p, t in s["tracked"].items() if now - t < self.c["STUDY_SEC"]}
        gaps = [round(bids[i][0] - bids[i + 1][0], 10) for i in range(len(bids) - 1)]
        tick = min(g for g in gaps if g > 0)
        bid0 = bids[0][0]
        start = s["bids"][0][0] if s["bids"] else bid0
        loc = self._local_med(notion)
        for d, p, nv in ripe[:2]:
            if p in s["tracked"] or len(self.study) > 60:
                continue
            best = None
            for i, ((q, _), v) in enumerate(zip(bids, notion)):
                if any(abs(q - a) <= 2 * tick for a in list(cands) + list(s["tracked"])):
                    continue
                if 0.5 * loc[i] <= v <= 1.5 * loc[i]:
                    dq = (bid0 - q) / bid0 * 1e4
                    if best is None or abs(dq - d) < best[0]:
                        best = (abs(dq - d), q, v, dq)
            if best is None or best[0] > 3.0:   # контроль только на том же расстоянии (±3 б.п.)
                continue
            s["tracked"][p] = now
            s["tracked"][best[1]] = now
            for kind, price, usdt, dist in (("wall", p, nv, d), ("ctrl", best[1], best[2], best[3])):
                self.study.append(dict(sym=s["name"], t=now, last=now, kind=kind, price=price, usdt=usdt,
                                       tick=tick, dist=dist, path=[[0, start]]))

    @staticmethod
    def _state(s):
        if s["pos"]:
            return "выход по рынку" if s["mkt"] else "в позиции"
        return "заявка выставлена" if s["order"] else "ждёт стенку"

    def book_view(self, sym):
        c = self.c
        if sym not in self.s:
            sym = c["PAIRS"][0]
        s, now = self.s[sym], time.time()
        out = dict(sym=sym, pairs=c["PAIRS"], state=self._state(s), bids=[], asks=[], marks=[],
                   wall=None, band=None, view=None, tick=0, dec=4, bid=None, ask=None, age=None)
        if not s["bids_snap"] or not s["asks_snap"]:
            return out
        bids, asks = s["bids_snap"], s["asks_snap"]
        bid = s["bids"][0][0] if s["bids"] else bids[0][0]
        ask = s["asks"][0][0] if s["asks"] else asks[0][0]
        gaps = [round(bids[i][0] - bids[i + 1][0], 10) for i in range(len(bids) - 1)]
        tick = min([g for g in gaps if g > 0] or [bid * 1e-4])
        lo, hi = bid * (1 - 100e-4), ask * (1 + 80e-4)
        out.update(bid=bid, ask=ask, age=round(now - s["snap_t"], 1), tick=tick, view=[lo, hi],
                   dec=len(("%.10f" % tick).rstrip("0").split(".")[1]),
                   bids=[[p, round(p * q, 1)] for p, q in bids if p >= lo],
                   asks=[[p, round(p * q, 1)] for p, q in asks if p <= hi],
                   band=[bid * (1 - c["MAX_DIST_BPS"] / 1e4), bid * (1 - c["MIN_DIST_BPS"] / 1e4)])
        o, p, m = s["order"], s["pos"], out["marks"]
        if p:
            m.append(dict(k="entry", price=p["entry"], label="вход (в позиции)"))
            if p.get("stop"):
                m.append(dict(k="stop", price=p["stop"], label="стоп"))
            if o and o["side"] == "sell":
                m.append(dict(k="tp", price=o["price"], label="тейк"))
            if p.get("wall"):
                out["wall"] = dict(price=p["wall"], usdt=p.get("usdt", 0), dist=(bid - p["wall"]) / bid * 1e4)
        elif o and o["side"] == "buy":
            m.append(dict(k="order", price=o["price"], label="заявка на покупку"))
            m.append(dict(k="stop", price=o["stop"], label="стоп (после входа)"))
            m.append(dict(k="tp", price=o["price"] * (1 + c["TP_BPS"] / 1e4), label="тейк (после входа)"))
            out["wall"] = dict(price=o["wall"], usdt=o["wall_usdt"], dist=(bid - o["wall"]) / bid * 1e4)
        elif s["wall"]:
            out["wall"] = s["wall"]
        return out

    def snapshot(self):
        d = super().snapshot()
        for x in d["syms"]:
            w = self.s[x["name"]]["wall"]
            x["obi"] = round(w["dist"], 1) if w else 0
        return d


