async def book(req):
    return web.json_response(req.app["eng"].book_view(req.query.get("sym", "")))


async def poll(eng):
    c = eng.c
    async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=10)) as ses:
        while True:
            for sym in c["PAIRS"]:
                try:
                    async with ses.get("https://api.binance.com/api/v3/depth",
                                       params={"symbol": sym, "limit": 500}) as r:
                        if r.status != 200:
                            print("depth http", r.status, flush=True)
                            await asyncio.sleep(30 if r.status in (418, 429) else 5)
                            continue
                        d = await r.json()
                    eng.on_snapshot(sym, [(float(a), float(b)) for a, b in d["bids"]],
                                    [(float(a), float(b)) for a, b in d["asks"]], time.time())
                except Exception:
                    traceback.print_exc()
                await asyncio.sleep(c["POLL"] / len(c["PAIRS"]))


async def main():
    db = sqlite3.connect(DB)
    db.executescript(SCHEMA2)
    eng = WallEngine(CFG, db)
    app = web.Application()
    app["eng"] = eng
    page = HTML.replace("<th>дисбаланс", "<th>до стенки б.п.").replace("OB paper bot", "Wall paper bot").replace("<th>возраст", "<th>данные, с назад").replace("<th>P/L б.п.", "<th>P/L с комиссией, б.п.")
    page = page.replace("<div id=o>", '<a href="/" style="color:#8bc">← стакан</a><div id=o>')
    app.router.add_get("/", lambda r: web.Response(text=CHART, content_type="text/html"))
    app.router.add_get("/stats", lambda r: web.Response(text=page, content_type="text/html"))
    app.router.add_get("/api", obbot.api)
    app.router.add_get("/book", book)
    runner = web.AppRunner(app)
    await runner.setup()
    await web.TCPSite(runner, "127.0.0.1", PORT).start()
    print("панель: http://127.0.0.1:%d" % PORT, flush=True)
    await asyncio.gather(feed(eng), poll(eng))


if __name__ == "__main__":
    asyncio.run(main())
